"""Generates eval artifacts for Method section — also called from clustering.py for auto-k."""
import pathlib, json
ROOT = pathlib.Path(__file__).parent
# clustering_eval.json already generated by mining.clustering --auto-k
# This script ensures it exists and adds association/outlier summaries

import sqlite3, pandas as pd, sys
sys.path.insert(0, str(pathlib.Path(__file__).parent.parent))
from database.db import get_connection
from dashboard.data_loader import latest_run

def build():
    out = {}
    c = get_connection()
    # association
    run = latest_run("association")
    if run:
        df = pd.read_sql_query("SELECT * FROM association_rules WHERE run_id=?", c, params=(run,))
        out["association"] = {"run_id": run, "n_rules": len(df), "avg_lift": float(df["lift"].mean()) if not df.empty else 0, "avg_conf": float(df["confidence"].mean()) if not df.empty else 0}
    # clustering -- already have file, merge
    clust = latest_run("clustering")
    if clust:
        df = pd.read_sql_query("SELECT * FROM customer_clusters WHERE run_id=?", c, params=(clust,))
        out["clustering"] = {"run_id": clust, "k": len(df), "sizes": df["size"].tolist() if not df.empty else []}
    # outliers
    outrun = latest_run("outlier")
    if outrun:
        df = pd.read_sql_query("SELECT COUNT(*) as n, SUM(is_outlier) as flag FROM outliers WHERE run_id=?", c, params=(outrun,))
        out["outliers"] = {"run_id": outrun, "flagged": int(df.iloc[0]["flag"] or 0), "total": int(df.iloc[0]["n"] or 0)}
    c.close()
    # merge with clustering_eval if exists
    ce = ROOT / "clustering_eval.json"
    if ce.exists():
        base = json.loads(ce.read_text())
        base.update(out)
        (ROOT / "eval_summary.json").write_text(json.dumps(base, indent=2))
        print("Wrote evals/eval_summary.json")
        print(json.dumps(base, indent=2))
    else:
        (ROOT / "eval_summary.json").write_text(json.dumps(out, indent=2))
        print(json.dumps(out, indent=2))

if __name__ == "__main__":
    build()
